package main
import("bytes";"fmt";"os";"path/filepath";"sort";"github.com/kdomanski/iso9660")
func main(){if len(os.Args)!=3{panic("explicit input directory and new output required")};entries,e:=os.ReadDir(os.Args[1]);if e!=nil{panic(e)};sort.Slice(entries,func(i,j int)bool{return entries[i].Name()<entries[j].Name()});w,e:=iso9660.NewWriter();if e!=nil{panic(e)};defer w.Cleanup();for _,entry:=range entries{if !entry.Type().IsRegular(){panic("only regular input files")};b,e:=os.ReadFile(filepath.Join(os.Args[1],entry.Name()));if e!=nil{panic(e)};if e=w.AddFile(bytes.NewReader(b),entry.Name());e!=nil{panic(e)}};f,e:=os.OpenFile(os.Args[2],os.O_CREATE|os.O_EXCL|os.O_WRONLY,0444);if e!=nil{panic(e)};if e=w.WriteTo(f,"vmruntime");e!=nil{panic(e)};if e=f.Sync();e!=nil{panic(e)};if e=f.Close();e!=nil{panic(e)};fmt.Println("DEV-only ISO created from exact listed inputs")}
